from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parent/'dist'
origin='https://sr-pool.de'
nav=[('/poolbau/','Poolbau'),('/poolarten/','Poolarten'),('/pflege-wartung/','Pflege & Wartung')]
regions=[('nordwest','Nordwesten','Oberkrämer bis Nauen',['Oberkrämer','Bötzow','Bärenklau','Vehlefanz','Schwante','Hennigsdorf','Velten','Schönwalde-Glien','Falkensee','Brieselang','Dallgow-Döberitz','Nauen'],'Vom kompakten Grundstück in Falkensee bis zum großzügigen Garten im Havelland: Wir stimmen Becken, Baustellenzufahrt und die Gestaltung der Terrasse auf Ihr Zuhause ab.'),('west','Westen','Potsdam & Havelland',['Potsdam','Werder (Havel)','Ketzin/Havel','Wustermark','Schwielowsee','Michendorf','Nuthetal','Kleinmachnow','Stahnsdorf','Teltow'],'Ein neuer Pool soll sich in den Garten einfügen. In Potsdam und im westlichen Berliner Umland planen wir deshalb Becken, Wege und Poolumrandung als zusammenhängendes Projekt.'),('sued','Süden','Teltow bis Königs Wusterhausen',['Großbeeren','Ludwigsfelde','Blankenfelde-Mahlow','Rangsdorf','Schönefeld','Schulzendorf','Zeuthen','Wildau','Königs Wusterhausen','Eichwalde','Mittenwalde'],'Ob Familienpool oder Schwimmbecken für sportliche Bahnen: Im südlichen Umland besprechen wir Nutzung, Technik und Platzbedarf gemeinsam. Auch die spätere Wartung wird von Anfang an mitgedacht.'),('ost','Osten','Erkner & östliches Umland',['Erkner','Woltersdorf','Schöneiche bei Berlin','Rüdersdorf bei Berlin','Fredersdorf-Vogelsdorf','Neuenhagen bei Berlin','Hoppegarten','Altlandsberg','Strausberg','Petershagen/Eggersdorf'],'Vom ersten Poolwunsch bis zum gepflegten Becken begleiten wir Ihr Projekt im östlichen Berliner Umland. Kurze Wege zu unserem Standort in Berlin-Kaulsdorf erleichtern die persönliche Abstimmung.'),('nord','Norden','Oranienburg & Barnim',['Oranienburg','Leegebruch','Birkenwerder','Hohen Neuendorf','Glienicke/Nordbahn','Mühlenbecker Land','Wandlitz','Panketal','Bernau bei Berlin','Ahrensfelde'],'Im Norden von Berlin stehen Garten, Grundstück und gewünschte Nutzung im Mittelpunkt. Wir besprechen passende Beckenbauweisen, die Anlieferung und einen Technikstandort, der später gut zugänglich bleibt.')]
types=[
('gfk','GFK-Fertigbecken','Fertigbecken','Ein vorgefertigter Beckenkörper aus glasfaserverstärktem Kunststoff mit glatter Oberfläche. Treppen und Sitzbereiche können bereits integriert sein.','Für alle, die eine klar definierte Form und einen vorgefertigten Beckenkörper wünschen.','Anlieferung, Kranstandort und Zufahrt müssen zur Beckengröße passen.'),
('pp','Polypropylen-Pool','Fertigbecken','Ein verschweißtes Kunststoffbecken aus PP. Je nach Hersteller sind individuelle Maße, Treppen und Ausstattungen möglich.','Für eine geradlinige Poolgestaltung mit abgestimmter Größe und Ausstattung.','Bodenplatte und Hinterfüllung werden nach den Vorgaben des gewählten Systems geplant.'),
('keramik','Keramik- & Composite-Pool','Fertigbecken','Mehrschichtige Fertigbecken, je nach System mit keramischer Verstärkung oder weiteren Verbundschichten.','Für einen vorgefertigten Pool mit hochwertiger Oberflächengestaltung.','Aufbau, Belastbarkeit und Pflegevorgaben unterscheiden sich je nach Hersteller.'),
('beton','Beton- & gemauerter Pool','Individualbau','Ein vor Ort gebauter Beckenkörper bietet viel Spielraum bei Form, Tiefe und Einstieg. Die Oberfläche kann mit Folie, geeigneten Fliesen oder anderen Systemen ausgeführt werden.','Für individuelle Grundrisse und besondere architektonische Wünsche.','Statik, Abdichtung und die geplante Oberfläche müssen als Gesamtsystem zusammenpassen.'),
('system','Systemstein- & Styroporpool','Individualbau','Schal- oder Systemsteine werden mit Beton verfüllt. Die Abdichtung erfolgt häufig durch eine passende Poolfolie.','Für ein individuell geplantes Becken mit modularer Bauweise.','Bewehrung, Beton, Untergrund und Auskleidung werden aufeinander abgestimmt.'),
('stahl','Stahlwandpool','Kompakte Lösungen','Ein Stahlwandbecken mit Folienauskleidung, häufig in runder, ovaler oder Achtform. Je nach System ist es aufstellbar, teilweise oder vollständig einzulassen.','Für kompakte Gärten und ein bewusst geplantes Einstiegskonzept.','Erforderliche Stützwände und zulässige Einbauart richten sich nach der jeweiligen Bauweise.'),
('edelstahl','Edelstahlpool','Individualbau','Ein Becken mit markanter Metalloberfläche, klarer Formensprache und individueller Ausstattung.','Für eine puristische Gestaltung und anspruchsvolle Poolarchitektur.','Werkstoff, Wasseraufbereitung und Wasserwerte müssen aufeinander abgestimmt sein.'),
('natur','Naturpool & Schwimmteich','Naturnahe Lösungen','Biologische Wasseraufbereitung statt klassischer Desinfektion. Naturpools und Schwimmteiche unterscheiden sich unter anderem in Gestaltung und Filterkonzept.','Für naturnahe Gärten und ein bewusst biologisches Wasserkonzept.','Flächenbedarf, Pflanzen- oder Filterbereiche und saisonale Pflege gehören in die Planung.'),
('aufstell','Aufstell- & Framepool','Kompakte Lösungen','Saisonale oder dauerhafte Aufstelllösungen mit Rahmen oder selbsttragender Konstruktion. Eine Alternative zum fest eingebauten Gartenpool.','Für begrenzte Flächen oder einen Einstieg in den eigenen Pool.','Tragfähiger, ebener Untergrund und eine zum Becken passende Filtertechnik sind entscheidend.')]
def btn(text='Poolberatung anfragen',url='/kontakt/',secondary=False):return f'<a class="btn {"secondary" if secondary else ""}" href="{url}">{text}</a>'
def image(src,alt,cls='',lazy=True):return f'<figure class="photo {cls}"><img src="/assets/{src}" alt="{alt}" width="1536" height="1024" {"loading=lazy" if lazy else "fetchpriority=high"}><figcaption>KI generiert · Pool-Inspiration</figcaption></figure>'
def kicker(t):return f'<p class="eyebrow">{t}</p>'
def intro(title,text,eyebrow):return f'<section class="page-intro wrap">{kicker(eyebrow)}<h1>{title}</h1><p class="lead">{text}</p></section>'
def callout():return f'<section class="cta"><div class="wrap cta-inner"><div>{kicker("DER ERSTE SCHRITT IST EIN GESPRÄCH")}<h2>Ihr Garten. Ihr Pool.<br>Unser gemeinsamer Plan.</h2><p>Erzählen Sie uns von Ihrer Idee. Wir besprechen, welche Lösung zu Ihrem Grundstück und Ihren Wünschen passt.</p></div>{btn()}</div></section>'
def footer():return '''<footer><div class="wrap footer-grid"><div><a class="footer-logo" href="/" aria-label="SR Pool Startseite"><span class="brand"><img src="/assets/sr-pool-logo.png" width="290" height="85" alt="SR Pool" loading="lazy"></span></a><p>Poolbau, Pflege und Wartung<br>in Berlin & Brandenburg.</p></div><div><h3>Entdecken</h3><a href="/poolbau/">Poolbau & Beratung</a><a href="/poolarten/">Alle Poolarten</a><a href="/pflege-wartung/">Pflege & Wartung</a></div><div><h3>Kontakt</h3><a href="tel:+4915111150592">Herr Schon · 0151 111 50 592</a><a href="tel:+4915155676584">Frau Lescau · 0151 556 76 584</a><a href="mailto:anfrage@srbauunternehmen.de">anfrage@srbauunternehmen.de</a><p>Mädewalder Weg 2 · 12621 Berlin<br>Mo–Fr · 08:00–16:00 Uhr</p></div></div><div class="wrap seo-footer"><details><summary>Poolbau in Berlin & Brandenburg</summary><div class="seo-region-links"><a href="/einsatzgebiet/">Berlin & Umland</a><a href="/einsatzgebiet/nordwest/">Oberkrämer & Nauen</a><a href="/einsatzgebiet/west/">Potsdam & Havelland</a><a href="/einsatzgebiet/sued/">Südliches Berliner Umland</a><a href="/einsatzgebiet/ost/">Erkner & östliches Umland</a><a href="/einsatzgebiet/nord/">Oranienburg & Barnim</a></div></details></div><div class="wrap footer-bottom"><span>© 2026 SR Pool · SR Bau GmbH</span><div><a href="https://www.srbaugmbh.de/impressum" target="_blank" rel="noopener">Impressum</a><a href="/datenschutz/">Datenschutz</a><a href="/assets/sr-pool-logo.png" download>Logo herunterladen</a></div></div></footer>'''
def page(path,title,desc,body):
 current='/'+path.strip('/')+'/' if path else '/'
 links=''.join(f'<a href="{url}" {"aria-current=page" if current==url else ""}>{text}</a>' for url,text in nav)
 schema={'@context':'https://schema.org','@type':'HomeAndConstructionBusiness','name':'SR Pool','legalName':'SR Bau GmbH','url':origin,'telephone':'+4915111150592','email':'anfrage@srbauunternehmen.de','address':{'@type':'PostalAddress','streetAddress':'Mädewalder Weg 2','postalCode':'12621','addressLocality':'Berlin','addressCountry':'DE'},'areaServed':['Berlin']+[x for r in regions for x in r[3]]}
 html=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | SR Pool</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{origin}{current}"><meta name="theme-color" content="#087dc1"><meta property="og:title" content="{escape(title)} | SR Pool"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{origin}{current}"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='6' fill='%23087dc1'/%3E%3Ctext x='16' y='22' font-family='Arial' font-weight='bold' font-size='18' text-anchor='middle' fill='white'%3ESR%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body><a class="skip" href="#main">Zum Inhalt</a><div class="topline"><div class="wrap"><span>Poolbau in Berlin & Brandenburg</span><a href="tel:+4915111150592">0151 111 50 592</a></div></div><header><div class="wrap header-inner"><a href="/" class="brand" aria-label="SR Pool Startseite"><img src="/assets/sr-pool-logo.png" width="290" height="85" alt="SR Pool"></a><button class="menu-toggle" aria-label="Menü öffnen" aria-expanded="false" aria-controls="navigation">Menü <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Hauptnavigation">{links}{btn('Kontakt & Beratung')}</nav></div></header><main id="main">{body}</main>{footer()}</body></html>'''
 dest=root/path/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(html)
steps=[('Beraten & verstehen','Wie möchten Sie Ihren Pool nutzen? Wir besprechen Größe, Bauweise, Ausstattung und Budgetrahmen.'),('Vor Ort planen','Grundstück, Zufahrt, Boden, Leitungen und Technikstandort bilden die Grundlage für ein nachvollziehbares Konzept.'),('Bauen & gestalten','Erdarbeiten, Beckeneinbau, Anschlüsse und Poolumrandung greifen sauber ineinander.'),('Starten & genießen','Wir nehmen die Anlage in Betrieb und erklären Wasserpflege, Steuerung und die nächsten Wartungsschritte.')]
def stepgrid():return '<div class="steps">'+''.join(f'<article><span class="step-number">0{i+1}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate(steps))+'</div>'
home=f'''<section class="hero"><div class="hero-copy">{kicker('SR POOL · BERLIN & BRANDENBURG')}<h1>Ein Stück<br>Urlaub.<br><em>Jeden Tag.</em></h1><p>Ihr eigener Pool. Von der ersten Idee bis zum Sprung ins Wasser – und mit Pflege und Wartung auch danach.</p><div class="button-row">{btn()}{btn('Poolarten entdecken','/poolarten/',True)}</div><div class="hero-note"><span>Beratung & Planung</span><span>Poolbau</span><span>Pflege & Wartung</span></div></div>{image('pool-hero.webp','Moderner rechteckiger Gartenpool mit blauer Wasserfläche und heller Terrasse','hero-photo',False)}</section><div class="service-strip wrap"><span>Individuell geplant</span><span>Passend zu Ihrem Garten</span><span>Rund um Berlin für Sie da</span></div><section class="wrap section intro-grid"><div>{kicker('VOM POOLWUNSCH ZUM LIEBLINGSPLATZ')}<h2>Mehr als ein Becken.<br>Ein neuer Ort zum Leben.</h2></div><div><p class="lead">Morgens ein paar Bahnen. Nachmittags Zeit mit der Familie. Abends einfach die Ruhe genießen.</p><p>SR Pool begleitet Sie auf dem Weg zu einem Pool, der zu Ihnen passt. Wir denken nicht nur an das Wasser: Technik, Einstieg, Terrasse und die spätere Pflege gehören von Anfang an dazu.</p><a class="text-link" href="/poolbau/">So entsteht Ihr Pool</a></div></section><section class="section pale"><div class="wrap"><div class="section-heading"><div>{kicker('DIE PASSENDE BAUWEISE')}<h2>So individuell<br>wie Ihr Garten.</h2></div><p>Fertigbecken, individuelle Bauweisen oder naturnahe Lösungen: Gemeinsam finden wir den richtigen Ausgangspunkt.</p></div><div class="type-preview">{''.join(f'<a class="type-tile" href="/poolarten/#{id}"><span class="tile-index">0{i+1}</span><h3>{t}</h3><p>{short}</p><span class="text-link">Beckenart kennenlernen</span></a>' for i,(id,t,short) in enumerate([('gfk','GFK & Composite','Vorgefertigte Becken mit klaren Formen und glatten Oberflächen.'),('beton','Beton & Systemstein','Viel Spielraum für individuelle Maße, Formen und Einstiege.'),('pp','PP & Edelstahl','Geradlinige Poolgestaltung mit durchdachter Ausstattung.')]))}</div><div class="section-bottom">{btn('Alle Beckenarten vergleichen','/poolarten/',True)}</div></div></section><section class="wrap section"><div class="section-heading"><div>{kicker('KLARE SCHRITTE · EIN GEMEINSAMES ZIEL')}<h2>Von der Idee<br>zum ersten Sprung.</h2></div><p>Eine gute Planung macht den Unterschied. Sie wissen, was als Nächstes ansteht – vom ersten Gespräch bis zur Einweisung.</p></div>{stepgrid()}</section><section class="care-split">{image('pool-detail.webp','Klares Poolwasser mit Einstiegsstufen, Hecke und Birken im Hintergrund','care-photo')}<div class="care-copy">{kicker('AUCH NACH DEM POOLBAU')}<h2>Das Wasser genießen.<br>Den Rest gut betreut wissen.</h2><p>Ein schöner Pool braucht Aufmerksamkeit. Wir unterstützen Sie bei Wasserpflege, Technik und saisonaler Vorbereitung – passend zu Ihrer Anlage.</p><ul class="clean-list"><li>Reinigung & Wasserpflege</li><li>Wartung von Filter- und Pooltechnik</li><li>Saisonstart & Einwinterung</li></ul>{btn('Pflege & Wartung entdecken','/pflege-wartung/')}</div></section><section class="wrap section inspiration"><div class="section-heading"><div>{kicker('POOLS, DIE HIER ZU HAUSE SIND')}<h2>Ihr Garten.<br>Eine neue Perspektive.</h2></div><p>Klare Wasserflächen, natürliche Pflanzung und eine Terrasse, die alles verbindet. So kann Ihr neuer Lieblingsplatz aussehen.</p></div><div class="inspiration-grid">{image('pool-garden.webp','Gartenpool in Brandenburg mit Terrasse, Rasen und heimischen Gehölzen')}{image('pool-types.webp','Kompakter Gartenpool an einem modernen Wohnhaus mit heimischen Hecken')}</div><p class="note">Individuell geplant für Ihr Zuhause in Berlin und dem umliegenden Brandenburg.</p></section>{callout()}'''
page('', 'Poolbau in Berlin & Brandenburg', 'SR Pool: Beratung, Planung und Poolbau bis zum fertigen Gartenpool. Dazu Pflege und Wartung in Berlin, Oberkrämer, Nauen, Potsdam, Erkner und Umgebung.',home)
body=intro('Ein guter Pool beginnt<br>mit einem guten Plan.','Vom ersten Gespräch bis zur fertigen Poolanlage: Wir verbinden Ihre Wünsche mit den Möglichkeiten Ihres Grundstücks.','BERATUNG · PLANUNG · POOLBAU')
body+=f'<section class="wrap editorial">{image("pool-garden.webp","Poolanlage mit Terrasse und heimischer Bepflanzung als Inspiration für Ihren Garten")}<div class="editorial-side"><h2>Der ganze Garten<br>zählt mit.</h2><p>Wie viel Platz steht zur Verfügung? Wo liegt die Sonne? Wie erreichen Baumaschinen und das Becken den Garten? Diese Fragen klären wir, bevor gebaut wird.</p><p>Wir stimmen Beckengröße, Einstieg und Technik auf die Nutzung ab und denken Wege, Terrasse und Poolumrandung mit. So entsteht ein Konzept, das optisch und im Alltag funktioniert.</p>{btn()}</div></section><section class="wrap section">{kicker("IHR PROJEKT IN VIER SCHRITTEN")}<h2>Nachvollziehbar geplant.<br>Sorgfältig umgesetzt.</h2>{stepgrid()}</section>'
body+='''<section class="pale section"><div class="wrap"><div class="section-heading"><h2>Was zur Planung gehört.</h2><p>Wir sprechen die Entscheidungen an, die später Bauablauf, Nutzung und laufenden Aufwand beeinflussen.</p></div><div class="feature-grid"><article><h3>Grundstück & Untergrund</h3><p>Zufahrt, Gelände, Bodenbeschaffenheit, vorhandene Leitungen und mögliche Wasserverhältnisse werden in die Planung einbezogen.</p></article><article><h3>Becken & Ausstattung</h3><p>Beckenart, Form, Tiefe und Einstieg passen zu Ihren Wünschen. Licht, Gegenstromanlage und Abdeckung planen wir bei Bedarf mit.</p></article><article><h3>Technik & Betrieb</h3><p>Filterung, Umwälzung, Wasseraufbereitung und optionale Heizung werden aufeinander abgestimmt. Auch Zugänglichkeit und Geräusche gehören dazu.</p></article><article><h3>Terrasse & Poolumrandung</h3><p>Geeignete Beläge, Entwässerung, Wege und Anschlüsse an den Garten ergeben eine stimmige Außenanlage.</p></article><article><h3>Umfang & Budget</h3><p>Ein Angebot macht deutlich, welche Arbeiten und Ausstattungen enthalten sind. Erdarbeiten und Zubehör werden mit betrachtet.</p></article><article><h3>Übergabe & Betreuung</h3><p>Nach der Inbetriebnahme erklären wir die Bedienung und Pflege. Bei Bedarf besprechen wir die weitere Wartung Ihrer Anlage.</p></article></div></div></section>'''+callout()
page('poolbau','Poolbau, Beratung & Planung','Von der Grundstücksbesichtigung über Erdarbeiten und Beckeneinbau bis zur Pooltechnik und Übergabe: SR Pool begleitet Ihr Poolprojekt rund um Berlin.',body)
body=intro('Welcher Pool<br>passt zu Ihnen?','Bauweise, Gestaltung und Nutzung entscheiden gemeinsam. Hier lernen Sie die wichtigsten Beckenarten und ihre Besonderheiten kennen.','BECKENARTEN IM ÜBERBLICK')
body+=f'<section class="wrap type-banner">{image("pool-types.webp","Gartenpool mit geradliniger Form, Rasen und heimischer Bepflanzung")}</section>'
body+='''<section class="wrap section-tight"><div class="filter-row" role="group" aria-label="Poolarten filtern">'''+''.join(f'<button class="filter {"active" if i==0 else ""}" aria-pressed="{str(i==0).lower()}" data-filter="{v}">{v}</button>' for i,v in enumerate(['Alle','Fertigbecken','Individualbau','Kompakte Lösungen','Naturnahe Lösungen']))+'</div><p class="muted" id="filter-count" aria-live="polite">9 Beckenarten im Überblick</p><div class="pool-grid">'
for i,(id,title,group,desc,fit,note) in enumerate(types):
 body+=f'<article class="pool-card" id="{id}" data-category="{group}"><div class="card-top"><span class="tile-index">{i+1:02}</span><span class="category">{group}</span></div><h2>{title}</h2><p>{desc}</p><details class="card-detail"><summary>Details zur Planung</summary><h3>Passt zu Ihnen</h3><p>{fit}</p><h3>Wichtig für die Planung</h3><p>{note}</p></details><a class="text-link" href="/kontakt/?pool={id}">Zu dieser Beckenart beraten lassen</a></article>'
body+='</div></section><section class="section pale"><div class="wrap"><div class="section-heading"><h2>Bauweise ist das eine.<br>Wasserführung das andere.</h2><p>Skimmer, Überlauf und Infinity sind Gestaltung und Wasserführung – sie können mit unterschiedlichen Beckenmaterialien kombiniert werden.</p></div><div class="feature-grid three"><article><h3>Skimmerpool</h3><p>Das Wasser steht unterhalb des Beckenrandes. Oberflächenwasser wird über einen Skimmer zur Filteranlage geführt.</p></article><article><h3>Überlaufpool</h3><p>Wasser fließt über den Beckenrand in eine Rinne. Ein abgestimmtes hydraulisches Konzept mit Ausgleichsbehälter ist Teil der Planung.</p></article><article><h3>Infinity-Pool</h3><p>Eine gezielt gestaltete Überlaufkante lässt die Wasserfläche optisch in die Umgebung übergehen. Grundstück und Blickachse bestimmen die Wirkung.</p></article></div><p class="note">Auch Indoor-Pools, kompakte Tauchbecken und Swim-Spas können Teil Ihrer Überlegungen sein. Welche Lösung auf Ihrem Grundstück umsetzbar ist, klären wir persönlich.</p></div></section>'+callout()
page('poolarten','Poolarten: GFK, PP, Beton, Edelstahl & mehr','Alle wichtigen Poolarten verständlich erklärt: GFK, Polypropylen, Keramik, Beton, Systemstein, Stahlwand, Edelstahl, Naturpool und Aufstellpool.',body)
body=intro('Damit Ihr Pool<br>ein Lieblingsplatz bleibt.','Wasserpflege, Reinigung und funktionierende Technik gehören zusammen. Wir unterstützen Sie im Alltag und beim Wechsel der Jahreszeiten.','PFLEGE & WARTUNG')
body+=f'<section class="wrap editorial">{image("pool-detail.webp","Poolwasser und Einstiegsbereich als Inspiration für einen gepflegten Pool")}<div class="editorial-side"><h2>Gute Pflege.<br>Von Anfang an.</h2><p>Wie wird die Filteranlage bedient? Was gehört zur regelmäßigen Kontrolle? Und welche Vorbereitung braucht der Pool im Winter? Wir erklären Ihre Anlage verständlich und begleiten Sie bei Bedarf weiter.</p>{btn("Wartung besprechen","/kontakt/?service=wartung")}</div></section>'
services=[('Wasserpflege & Kontrolle','Wir prüfen die Wasserwerte im Zusammenhang mit dem jeweiligen Aufbereitungssystem und besprechen die passende Pflege. Die Vorgaben Ihrer Anlage und der verwendeten Produkte bilden die Grundlage.'),('Poolreinigung','Boden, Wände, Wasserlinie und zugängliche Einbauteile brauchen regelmäßige Reinigung. Wir beraten zu geeigneten Geräten und unterstützen Sie bei der Pflege.'),('Filter & Umwälzung','Wir kontrollieren die Funktion der Filtertechnik, Pumpen und zugänglichen Verbindungen. Notwendige Reinigung und Wartung werden an das System angepasst.'),('Heizung & Steuerung','Heizung, Regelung und Dosiertechnik sollen zuverlässig zusammenarbeiten. Wir besprechen Funktionskontrollen, Einstellungen und Wartungsbedarf.'),('Saisonstart','Vor der Badesaison prüfen wir den Zustand Ihrer Anlage, reinigen erforderliche Bereiche und bereiten die Wiederinbetriebnahme nach Herstellervorgaben vor.'),('Einwinterung','Abdeckung, Leitungen und Technik werden passend zur Bauweise für die kalte Jahreszeit vorbereitet. Der Ablauf richtet sich nach Ihrer konkreten Anlage.')]
body+='<section class="wrap section"><div class="feature-grid">'+''.join(f'<article><span class="tile-index">{i+1:02}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate(services))+'</div></section><section class="wrap compact-faq"><details><summary>Fragen zur Poolpflege</summary><div class="faq-content">'
faqs=[('Wie häufig sollte mein Pool gewartet werden?','Das hängt von Nutzung, Anlage und Wasseraufbereitung ab. Wir stimmen regelmäßige Kontrollen und Wartung mit Ihnen auf Ihr Becken ab.'),('Betreuen Sie auch einen bestehenden Pool?','Sprechen Sie uns an. Wir sehen uns Bauweise und Technik an und klären, welche Pflege- und Wartungsleistungen für Ihre bestehende Anlage möglich sind.'),('Ist ein Salzwasserpool pflegefrei?','Auch bei einer Salzelektrolyse sind Wasserwerte, Filteranlage und Technik regelmäßig zu kontrollieren. Außerdem müssen Materialien und Bauteile zum System passen.'),('Kann mein Poolwasser im Winter im Becken bleiben?','Das richtet sich nach Becken, Einbauteilen und Herstellervorgaben. Wir besprechen die geeignete Einwinterung für Ihre Anlage, statt einen pauschalen Ablauf anzuwenden.')]
body+=''.join(f'<article><h3>{q}</h3><p>{a}</p></article>' for q,a in faqs)+'</div></details></section>'+callout()
page('pflege-wartung','Poolpflege, Wartung & Einwinterung','SR Pool unterstützt bei Poolreinigung, Wasserpflege, Filtertechnik, Saisonstart und Einwinterung in Berlin und dem umliegenden Brandenburg.',body)
body=intro('Poolbau in Berlin<br>& Brandenburg.','Von Oberkrämer und Nauen über Potsdam und den Berliner Süden bis Erkner – und über das östliche und nördliche Umland zurück.','UNSER EINSATZGEBIET')
body+='<section class="wrap section-tight region-overview"><p>Wir begleiten Poolprojekte in ganz Berlin und dem umliegenden Brandenburg. Unser Standort ist der Mädewalder Weg 2 in Berlin-Kaulsdorf.</p><div class="region-overview-links">'+''.join(f'<a href="/einsatzgebiet/{slug}/">{title}</a>' for slug,label,title,towns,text in regions)+'</div><p class="note">Ihr Ort liegt dazwischen? Sprechen Sie uns an – wir klären die Möglichkeiten persönlich.</p></section>'+callout()
page('einsatzgebiet','Poolbau rund um Berlin: Oberkrämer bis Nauen & Erkner','Unser Einsatzgebiet: Berlin, Oberkrämer, Nauen, Falkensee, Potsdam, Teltow, Schönefeld, Königs Wusterhausen, Erkner, Bernau und das umliegende Brandenburg.',body)
for slug,label,title,towns,text in regions:
 body=intro(f'Poolbau im {label.lower()}<br>von Berlin.',f'{text}',title.upper())
 body+='<section class="wrap section-tight intro-grid"><div><h2>Von der Beratung<br>bis zum fertigen Pool.</h2><p>Ihr Poolprojekt beginnt mit einem Gespräch über Ihre Wünsche. Anschließend stimmen wir Beckenbauweise, Grundstück und Technik aufeinander ab. Auch Terrasse, Einstieg und Poolumrandung gehören zu einem durchdachten Ergebnis.</p><p>Für Fertigbecken prüfen wir die Anlieferung. Bei individuell gebauten Becken besprechen wir Form, Größe und Ausführung. So wissen Sie, welche Schritte und Arbeiten Ihr Projekt umfasst.</p>'+btn()+'</div><div class="regional-box">'+kicker('HIER SIND WIR FÜR SIE TÄTIG')+f'<h3>{title}</h3><ul class="town-list">'+''.join(f'<li>{t}</li>' for t in towns)+'</ul></div></section><section class="pale section"><div class="wrap"><h2>Planung, Bau und Betreuung.</h2>'+stepgrid()+'<div class="button-row">'+btn('Beckenarten kennenlernen','/poolarten/',True)+btn('Pflege & Wartung','/pflege-wartung/',True)+'</div></div></section><section class="wrap compact-faq narrow"><details><summary>Fragen zum Poolbau in Ihrer Region</summary><div class="faq-content"><article><h3>Welche Beckenart passt auf mein Grundstück?</h3><p>Wir berücksichtigen Platz, Gelände, Zugang und Ihre Wünsche. Fertigbecken, PP, GFK, Beton, Systemstein und weitere Bauweisen werden im Gespräch gegeneinander abgewogen.</p></article><article><h3>Kann ich auch Pflege für meinen vorhandenen Pool anfragen?</h3><p>Ja. Nennen Sie uns Ihren Ort, die Beckenart und die vorhandene Technik. Wir klären gemeinsam den möglichen Umfang der Betreuung.</p></article></div></details></section>'+callout()
 page('einsatzgebiet/'+slug,'Poolbau '+title+' – Beratung & Wartung','SR Pool: Poolbau, Beratung, Pflege und Wartung in '+', '.join(towns)+'.',body)
body=intro('Ihr Pool beginnt<br>mit Ihrer Idee.','Erzählen Sie uns, was Sie sich wünschen. Sie erreichen das Team der SR Bau GmbH telefonisch oder per E-Mail.','KONTAKT & BERATUNG')
body+='''<section class="wrap contact-grid section-tight"><div><h2>Persönlich für Sie da.</h2><div class="contact-item"><span>Office Manager · Herr Schon</span><a href="tel:+4915111150592">0151 111 50 592</a></div><div class="contact-item"><span>Büro · Frau Lescau</span><a href="tel:+4915155676584">0151 556 76 584</a></div><div class="contact-item"><span>E-Mail</span><a class="email-address" href="mailto:anfrage@srbauunternehmen.de">anfrage@srbauunternehmen.de</a></div><div class="contact-item"><span>Standort & Erreichbarkeit</span><p>SR Bau GmbH · SR Pool<br>Mädewalder Weg 2<br>12621 Berlin<br>Montag–Freitag · 08:00–16:00 Uhr</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=M%C3%A4dewalder+Weg+2+12621+Berlin" target="_blank" rel="noopener">Route planen</a></div></div><form id="inquiry" class="inquiry"><h2>Poolwunsch beschreiben.</h2><p>Diese Angaben werden als E-Mail vorbereitet. Sie versenden die Nachricht anschließend selbst in Ihrem E-Mail-Programm.</p><label for="name">Ihr Name</label><input id="name" name="name" autocomplete="name" required maxlength="100"><div class="form-row"><div><label for="email">E-Mail-Adresse</label><input id="email" name="email" type="email" autocomplete="email" required></div><div><label for="place">Ort des Projekts</label><input id="place" name="place" autocomplete="address-level2" required></div></div><label for="service">Worum geht es?</label><select id="service" name="service"><option value="Poolbau & Beratung">Poolbau & Beratung</option><option value="Pflege & Wartung">Pflege & Wartung</option><option value="Bestehender Pool">Bestehender Pool</option></select><label for="pool">Gewünschte Beckenart</label><select id="pool" name="pool"><option value="Noch offen">Noch offen – bitte beraten</option>'''+''.join(f'<option value="{t}" data-id="{id}">{t}</option>' for id,t,*_ in types)+'''</select><label for="message">Ihre Wünsche</label><textarea id="message" name="message" rows="5" placeholder="Zum Beispiel: verfügbare Fläche, gewünschte Größe oder Fragen zu einer bestehenden Anlage." required maxlength="5000"></textarea><button type="submit" class="btn">Anfrage als E-Mail vorbereiten</button><p class="note">Ihre Eingaben werden hier nicht gespeichert. Erst beim Versand über Ihr E-Mail-Programm wird die Nachricht übermittelt. <a href="/datenschutz/">Datenschutzhinweise</a></p><p id="form-status" role="status"></p><div id="mail-fallback" hidden><label for="mail-text">Vorbereitete Nachricht zum Kopieren</label><textarea id="mail-text" readonly rows="8"></textarea><button type="button" class="btn secondary" id="copy-mail">Nachricht kopieren</button></div></form></section>'''
page('kontakt','Kontakt & Poolberatung','Kontakt zu SR Pool / SR Bau GmbH in Berlin-Kaulsdorf. Poolberatung anfragen unter 0151 111 50 592 oder anfrage@srbauunternehmen.de.',body)
body=intro('Datenschutzhinweise','Informationen zu den Datenverarbeitungen auf dieser Website.','SR POOL')+'''<section class="wrap narrow legal"><h2>Verantwortlicher</h2><p>SR Bau GmbH, Mädewalder Weg 2, 12621 Berlin.<br>E-Mail: <a href="mailto:info@srbauunternehmen.de">info@srbauunternehmen.de</a><br>Büro: <a href="tel:+4915155676584">0151 556 76 584</a></p><h2>Website-Aufruf</h2><p>Beim Aufruf einer Website verarbeitet der Hostingdienst technische Verbindungsdaten, zum Beispiel IP-Adresse, aufgerufene Adresse, Zeitpunkt und Browserinformationen, zur Bereitstellung und Sicherheit des Angebots. Diese Website wird bei Hetzner gehostet.</p><h2>Anfragen</h2><p>Das Formular bereitet Ihre Angaben lokal im Browser als E-Mail vor. Es speichert die Eingaben nicht in einer Datenbank und versendet keine Nachricht automatisch. Wenn Sie die E-Mail über Ihr E-Mail-Programm senden oder direkt Kontakt aufnehmen, verarbeitet die SR Bau GmbH die von Ihnen übermittelten Angaben zur Bearbeitung Ihrer Anfrage.</p><h2>Externe Links</h2><p>Eine Kartenanwendung wird erst geöffnet, wenn Sie den Link zur Routenplanung anklicken. Es ist keine externe Karte in diese Website eingebettet. Bei externen Angeboten gelten die Datenschutzhinweise des jeweiligen Anbieters.</p><h2>Analyse und Werbedienste</h2><p>Diese Website bindet keine eigenen Analyse- oder Werbeskripte ein. Schrift und Bilddateien werden zusammen mit der Website ausgeliefert.</p><h2>Weitere Informationen</h2><p>Für weiterführende Angaben zu Ihren Rechten und zur Datenverarbeitung durch die SR Bau GmbH beachten Sie die <a href="https://www.srbaugmbh.de/datenschutz" target="_blank" rel="noopener">Datenschutzinformationen des Unternehmens</a>. Fragen richten Sie bitte an die oben genannten Kontaktdaten.</p></section>'''
page('datenschutz','Datenschutz','Datenschutzhinweise zu SR Pool und zur Kontaktaufnahme mit der SR Bau GmbH.',body)
