css+='\n.brand{display:block;position:relative;aspect-ratio:1893/406;overflow:hidden}.brand img{position:absolute;width:112.94%;max-width:none;height:auto;left:-6.708%;top:-48.768%;object-fit:initial}.inspiration-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:26px}.inspiration-grid .photo{height:390px}.inspiration-grid .photo:last-child{margin-top:55px}.inspiration .note{margin-top:25px}.type-banner{margin-bottom:42px}.type-banner .photo{height:400px}.type-banner img{object-position:center 63%}.compact-faq{padding-bottom:55px}.compact-faq>details{border-top:1px solid #c5d7e2;padding:18px 0}.compact-faq>details>summary{font-size:1rem;color:#456374}.faq-content{display:grid;grid-template-columns:1fr 1fr;gap:26px;padding:25px 0 5px}.faq-content h3{font-size:1rem;line-height:1.5;letter-spacing:0}.faq-content p{font-size:.95rem;margin-top:12px}.card-detail{padding:14px 0 0;border-bottom:0}.card-detail summary{font-size:.85rem;color:#38677f;font-weight:600}.card-detail h3{margin-top:20px}.seo-footer{margin-top:32px}.seo-footer details{border-top:1px solid #ffffff26;border-bottom:0;padding:16px 0 0}.seo-footer summary{font-size:.85rem;font-weight:400;color:#a6bdcb}.seo-region-links{display:flex;flex-wrap:wrap;gap:10px 25px;padding:20px 0 0;color:#c0d7e4}.footer-bottom{margin-top:25px}.region-overview{max-width:900px}.region-overview-links{display:flex;flex-wrap:wrap;gap:12px 28px;margin-top:25px}.region-overview-links a{color:#076d9e;border-bottom:1px solid #b5d5e6;padding:8px 0}.region-overview .note{margin-top:30px}@media(max-width:650px){.inspiration-grid,.faq-content{grid-template-columns:1fr;gap:22px}.inspiration-grid .photo{height:290px}.inspiration-grid .photo:last-child{margin-top:0}.type-banner .photo{height:280px}.compact-faq{padding-bottom:35px}.region-overview-links{gap:8px 20px}}\n'
css += '\nfooter .footer-logo{display:inline-block!important;background:#fff;padding:16px 18px;border-radius:4px;width:258px;max-width:100%;margin-bottom:8px}footer .footer-logo .brand{width:222px;max-width:100%}\n'
(root/'assets/site.css').write_text(css)
js='''const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);menu.setAttribute('aria-label',open?'Menü schließen':'Menü öffnen')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});let count=0;document.querySelectorAll('[data-category]').forEach(c=>{const show=b.dataset.filter==='Alle'||c.dataset.category===b.dataset.filter;c.hidden=!show;if(show)count++});document.querySelector('#filter-count').textContent=count+' Beckenarten im Überblick'}));const form=document.querySelector('#inquiry');if(form){const params=new URLSearchParams(location.search);const pool=params.get('pool');const option=[...document.querySelector('#pool').options].find(x=>x.dataset.id===pool);if(option)option.selected=true;if(params.get('service')==='wartung')document.querySelector('#service').value='Pflege & Wartung';form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const msg=['Guten Tag,','', 'ich interessiere mich für '+data.get('service')+'.','Name: '+data.get('name'),'E-Mail: '+data.get('email'),'Projektort: '+data.get('place'),'Beckenart: '+data.get('pool'),'','Meine Wünsche:',data.get('message')].join('\\n');document.querySelector('#mail-text').value=msg;document.querySelector('#mail-fallback').hidden=false;document.querySelector('#form-status').textContent='Ihre Nachricht ist vorbereitet. Bitte senden Sie diese in Ihrem E-Mail-Programm. Falls es sich nicht öffnet, kopieren Sie den Text und senden ihn an anfrage@srbauunternehmen.de.';location.href='mailto:anfrage@srbauunternehmen.de?subject='+encodeURIComponent('SR Pool – '+data.get('service')+' in '+data.get('place'))+'&body='+encodeURIComponent(msg)});document.querySelector('#copy-mail').addEventListener('click',async()=>{const text=document.querySelector('#mail-text');try{await navigator.clipboard.writeText(text.value);document.querySelector('#form-status').textContent='Nachricht kopiert. Bitte in Ihre E-Mail an anfrage@srbauunternehmen.de einfügen und versenden.'}catch{text.focus();text.select();document.querySelector('#form-status').textContent='Bitte kopieren Sie den markierten Nachrichtentext.'}})}'''
(root/'assets/site.js').write_text(js)
paths=['/']+['/'+str(p.parent.relative_to(root)).strip('/')+'/' for p in root.rglob('index.html') if p.parent!=root]
(root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+origin+p+'</loc></url>' for p in paths)+'</urlset>')
(root/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+origin+'/sitemap.xml\n')
print('Created',len(paths),'pages')
